insert into public.indicator_groups (
  form_version_id,
  code,
  name,
  source_name,
  inferred_name,
  display_order,
  source_start_row,
  source_end_row,
  observation_source_range
)
select
  active_form.id,
  group_seed.code,
  group_seed.name,
  group_seed.source_name,
  group_seed.inferred_name,
  group_seed.display_order,
  group_seed.source_start_row,
  group_seed.source_end_row,
  group_seed.observation_source_range
from group_seed
cross join active_form
on conflict (form_version_id, code) do update
set name = excluded.name,
    source_name = excluded.source_name,
    inferred_name = excluded.inferred_name,
    display_order = excluded.display_order,
    source_start_row = excluded.source_start_row,
    source_end_row = excluded.source_end_row,
    observation_source_range = excluded.observation_source_range,
    active = true,
    updated_at = now();

