  active_form.id,
  indicator_groups.id,
  special_seed.code,
  special_seed.label,
  special_seed.parent_label,
  special_seed.source_cell,
  special_seed.proposed_value_cell_or_range,
  special_seed.proposed_data_type::public.indicator_data_type,
  special_seed.model_status::public.special_model_status,
  special_seed.requires_confirmation,
  special_seed.notes
from special_seed
cross join active_form
join public.indicator_groups on indicator_groups.form_version_id = active_form.id
  and indicator_groups.code = special_seed.group_code
on conflict (form_version_id, code) do update
set label = excluded.label,
    parent_label = excluded.parent_label,
    source_cell = excluded.source_cell,
    proposed_value_cell_or_range = excluded.proposed_value_cell_or_range,
    proposed_data_type = excluded.proposed_data_type,
